/// An account's blob-storage metrics as the relay reports them — the response shape
/// of `GET /v1/accounts/{did}/storage` (`StorageResponse` in crates/pds/src/routes/
/// account_storage.rs; shared by value like [`AccountUsage`], pinned by a
/// deserialization test). Re-serialized camelCase over IPC.
#[derive(Debug, Clone, PartialEq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountStorage {
    pub blob_count: i64,
    pub total_bytes: i64,
    pub quota_bytes: i64,
    pub quota_used_pct: f64,
    pub largest_blob: Option<LargestBlob>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LargestBlob {
    pub cid: String,
    pub size: i64,
}

/// The relay's post-sweep report — the response shape of
/// `POST /v1/admin/accounts/{did}/revoke-credentials` (`RevokeCredentialsResponse` in
/// crates/pds/src/routes/admin_revoke_credentials.rs; shared by value like
/// [`AccountUsage`], pinned by a deserialization test). Re-serialized camelCase over
/// IPC so the screen renders the counts verbatim.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RevokedCredentials {
    pub sessions_revoked: i64,
    pub app_passwords_revoked: i64,
    pub oauth_tokens_revoked: i64,
    pub oauth_codes_revoked: i64,
    pub transfer_device_tokens_revoked: i64,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RepairedEmail {
    pub did: String,
    pub email: String,
    pub email_confirmed: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct IssuedResetToken {
    pub did: String,
    pub token: String,
    pub expires_in: u32,
}

/// A page of the relay's account list — the response shape of `GET /v1/admin/accounts`
/// (`ListAccountsResponse` in crates/pds/src/routes/admin_list_accounts.rs; shared by
/// value like [`AccountUsage`], pinned by a deserialization test). Re-serialized
/// camelCase over IPC. `cursor` is omitted by the relay on the last page (serde reads
/// a missing `Option` as `None`; it re-serializes as `null` over IPC).
#[derive(Debug, Clone, PartialEq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountList {
    pub accounts: Vec<AccountListEntry>,
    /// The configured per-account storage quota in bytes — one value for every row.
    pub quota_bytes: i64,
    /// Accounts matching the current filters that carry at least one labeler flag —
    /// stated per response because flagged accounts can sit on later pages. Defaulted so
    /// a pre-labeler-watching relay (which omits the field) still parses.
    #[serde(default)]
    pub flagged_total: i64,
    pub cursor: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountListEntry {
    pub did: String,
    /// The account's first-created handle, or `None` when it has none.
    pub handle: Option<String>,
    pub created_at: String,
    /// Derived lifecycle: `active`, `deactivated`, `suspended`, or `takendown` —
    /// always stated explicitly by this endpoint.
    pub status: String,
    /// Total bytes of the account's owned blobs.
    pub total_bytes: i64,
    /// `total_bytes` as a percentage of `quota_bytes`.
    pub quota_used_pct: f64,
    /// Labels currently in force from the relay's watched labelers, newest first; empty
    /// for an unflagged account. Defaulted so a pre-labeler-watching relay still parses.
    #[serde(default)]
    pub flags: Vec<AccountFlag>,
}

/// One in-force label on an account, as observed by the relay from a watched labeler.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountFlag {
    /// The label value (e.g. `spam`, `!hide`).
    pub val: String,
    /// DID of the labeler that applied the label.
    pub labeler_did: String,
    /// The labeler's label-creation timestamp.
    pub cts: String,
}

/// The relay's server-health readout — the response shape of `GET /v1/admin/health`
/// (`HealthResponse` in crates/pds/src/routes/admin_health.rs; shared by value like
/// [`AccountUsage`], pinned by a deserialization test). Literal facts only — the relay
/// derives no ok/warn verdicts; any staleness judgment is the screen's. Re-serialized
/// camelCase over IPC.
#[derive(Debug, Clone, PartialEq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ServerHealth {
    pub version: String,
    pub uptime_seconds: u64,
    pub accounts: HealthAccounts,
    pub storage: HealthStorage,
    pub firehose: HealthFirehose,
    pub sweeps: HealthSweeps,
}

/// Derived-lifecycle buckets; the four non-total buckets partition `total` exactly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HealthAccounts {
    pub total: i64,
    pub active: i64,
    pub deactivated: i64,
    pub suspended: i64,
    pub takendown: i64,
    /// Accounts carrying at least one in-force label from a watched labeler — the
    /// console's flagged badge count. Orthogonal to the lifecycle buckets, and always 0
    /// when the relay watches no labelers. Defaulted so a pre-labeler-watching relay
    /// (which omits the field) still parses.
    #[serde(default)]
    pub flagged: i64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HealthStorage {
    pub blob_count: i64,
    pub blob_bytes: i64,
    pub block_count: i64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HealthFirehose {
    pub current_seq: u64,
    pub subscribers: u64,
    pub retained_events: i64,
    /// Age in seconds of the oldest retained event; `None` when the log is empty.
    pub backfill_window_seconds: Option<i64>,
}

/// Each field is `None` until that sweep's first completed pass after boot.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HealthSweeps {
    pub blob_gc: Option<HealthSweepRun>,
    pub firehose_gc: Option<HealthSweepRun>,
    pub account_reaper: Option<HealthSweepRun>,

