63	  const identity = $derived(pairing ? serverIdentity(pairing) : null);
64	  const normalizedEmail = $derived(email.trim().toLowerCase());
65	  const emailLooksValid = $derived(/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(normalizedEmail));
66	
67	  // The address the operator reviewed when they armed the confirm. If the field drifts
68	  // from it, auto-disarm — a second tap must never sign a value the operator didn't review
