118	  // so defaulting an absent field to it would fabricate an all-clear an old relay never
119	  // gave. "not reported" is the only honest reading.
120	  it('never collapses an unreported pair into the reported all-clear', () => {
121	    const unreported = unownedBlobLine(null, null);
122	    expect(unreported).toEqual({ line: 'not reported', alarm: false });
123	    expect(unreported.line).not.toBe(unownedBlobLine(0, 0).line);
124	  });
125	
126	  it('treats a half-reported pair as unanswered — a half-answer is no answer', () => {
127	    expect(unownedBlobLine(2, null).line).toBe('not reported');
128	    expect(unownedBlobLine(null, 4096).line).toBe('not reported');
129	  });
130	
131	  // An unanswerable question is not an alarm: raising one on every older relay would
132	  // train the operator to dismiss the row that actually matters.
133	  it('raises the alarm only for a reported, standing population', () => {
134	    expect(unownedBlobLine(null, null).alarm).toBe(false);
135	    expect(unownedBlobLine(0, 0).alarm).toBe(false);
136	    expect(unownedBlobLine(1, 10).alarm).toBe(true);
137	  });
138	
139	  // Status is text + glyph + position, never color (AAA) — and the glyph means something
140	  // only if the quiet states stay unmarked.
141	  it('carries the state as text and marks the line exactly once', () => {
142	    const alarming = unownedBlobLine(7, 900_000).line;
143	    expect(alarming).toContain('ownership lost');
144	    expect(alarming.match(/!/g)).toHaveLength(1);
145	    expect(unownedBlobLine(0, 0).line).not.toContain('!');
146	    expect(unownedBlobLine(null, null).line).not.toContain('!');
147	  });
148	});

