      flags: flagged
        ? i === accountCount - flaggedCount
          ? [makeFlag('spam'), makeFlag('!hide', '2026-07-15T10:30:00Z')]
          : [makeFlag('platform-manipulation')]
        : [],
    });
  });
  return {
    pairingId,

